			erey2.Add(new BlockFalling(984, -96, scale, false, true));
			erey.Add(new BlockFalling(1016, -96, scale, false, true));
			erey2.Add(new BlockFalling(1048, -96, scale, false, true));
			erey.Add(new BlockFalling(1080, -96, scale, false, true));
			erey.Add(new BlockFalling(1112, -96, scale, false, true));
			erey.Add(new BlockFalling(1144, -96, scale, false, true));
			erey.Add(new BlockFalling(1176, -96, scale, false, true));
			erey.Add(new BlockFalling(1208, -96, scale, false, true));
			erey.Add(new BlockFalling(1240, -96, scale, false, true));
			FlxG.camera.setBounds(0, 0, 1280, 360, true);
			FlxG.camera.follow(player, FlxCamera.STYLE_LOCKON);
		}

		public override void update()
		{
			base.update();
			if (!startedToRainBlocks && count == 0 && player.x > 44)
			{
				startedToRainBlocks = true;
			}

			if (startedToRainBlocks)
			{
				if (count < erey.Count && erey[count].x < player.x - 8)
				{
					blocks.add(erey[count]);
					++count;
				}

				if (count2 < erey2.Count && erey2[count2].x < player.x + 168)
				{
					blocks.add(erey2[count2]);
					++count2;
				}

				if (count3 < erey3.Count && erey3[count3].x < player.x - 120)
				{
					blocks.add(erey3[count3]);
					++count3;
				}

				if (count >= erey.Count && count2 >= erey2.Count && count3 >= erey3.Count)
				{
					startedToRainBlocks = false;
				}

				for (i = 0; i < count; ++i)
				{
					if (erey[i].x < player.x - 400)
					{
						erey[i].kill();
					}
				}

				for (i = 0; i < count2; ++i)
				{
					if (erey2[i].x < player.x - 400)
					{
						erey2[i].kill();
					}
				}
			}

			if (player.y > 360)
			{
				instantDeath();
			}

			FlxG.collide<Hans, FlxSprite>(player, blocks, blockCollision);
			FlxG.collide<FlxTilemap, BlockFalling>(level, blocks, blockParticle);
			FlxG.collide(blocks);
		}

		public override void getWell()
		{
			FlxG.bgColor = 4290199552;
		}

		public override void nextLevel()
		{
			FlxG.switchState(new Level28());
		}
	}
